/* Auto-generated: Phoenix sit pose cutout (transparent) for neon cinematic scene. */
(function(){
  var url="data:image/png;base64,";
  function maskTints(img){
    var root=img.closest("#phoenix")||document.getElementById("phoenix");
    if(!root) return;
    root.querySelectorAll(".tint, .tint2").forEach(function(el){
      el.style.webkitMaskImage="url("+url+")";
      el.style.maskImage="url("+url+")";
      el.style.webkitMaskSize="contain";
      el.style.maskSize="contain";
      el.style.webkitMaskRepeat="no-repeat";
      el.style.maskRepeat="no-repeat";
      el.style.webkitMaskPosition="left bottom";
      el.style.maskPosition="left bottom";
    });
  }
  function apply(){
    document.querySelectorAll("img.phoenix-still").forEach(function(img){
      if(!img.dataset.sitSrcApplied){
        img.dataset.sitSrcApplied="1";
        img.src=url;
      }
      maskTints(img);
    });
  }
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",apply);
  else apply();
  var obs=new MutationObserver(apply);
  if(document.documentElement) obs.observe(document.documentElement,{childList:true,subtree:true,attributes:true});
})();
